insert into public.roles (name, description, permissions, is_test) values ('super_admin', 'Full access', '{"can_access_admin":true,"can_manage_settings":true,"can_manage_roles":true,"can_manage_pricing":true,"can_manage_shops":true,"can_manage_users":true,"can_manage_support":true,"can_manage_own_shop":true}'::jsonb, false) on conflict (name) do nothing;
