update public.app_settings set category = 'login', description = 'Role given to everyone else when they first log in.' where key = 'DEFAULT_ROLE_NAME';
update public.app_settings set category = 'appearance', description = 'App colours for light and dark mode.' where key = 'THEME_COLORS';
update public.app_settings set category = 'appearance', description = 'Logo in the header: a file of the app or a web link to an image.' where key = 'APP_LOGO_URL';
update public.app_settings set category = 'appearance', description = 'Company name, link and logo in the "Powered by" line.' where key = 'BRAND';
update public.app_settings set category = 'appearance', description = 'How long pop-up messages stay on screen, in milliseconds. 3500 = 3.5 seconds.' where key = 'TOAST_DURATION_MS';
update public.app_settings set category = 'advanced', description = 'Icon files used when the app is installed.' where key = 'APP_ICONS';
update public.app_settings set category = 'advanced', description = 'Storage bucket for bill photos.' where key = 'BILLS_BUCKET';
update public.app_settings set category = 'advanced', description = 'Storage bucket for profile photos.' where key = 'AVATARS_BUCKET';
update public.app_settings set category = 'advanced', description = 'Bill photos are shrunk to max_px pixels and quality (0-1) before upload.' where key = 'BILL_IMAGE';
